package com.northstarbank.core;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;
@Entity @Table(name="customers") class CoreCustomer{@Id String id;String fullName;String phone;String email;String branch;boolean vulnerable;protected CoreCustomer(){}CoreCustomer(String i,String n,String p,String e,String b,boolean v){id=i;fullName=n;phone=p;email=e;branch=b;vulnerable=v;}}
@Entity @Table(name="accounts") class CoreAccount{@Id String accountNumber;String customerId;String product;String currency;String status;BigDecimal balance;protected CoreAccount(){}CoreAccount(String n,String c,String p,BigDecimal b){accountNumber=n;customerId=c;product=p;currency="GBP";status="active";balance=b;}}
@Entity @Table(name="transactions") class CoreTransaction{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;String accountNumber;LocalDate bookingDate;BigDecimal amount;String currency;String description;String channel;String reference;protected CoreTransaction(){}CoreTransaction(String a,LocalDate d,BigDecimal v,String x,int i){accountNumber=a;bookingDate=d;amount=v;currency="GBP";description=x;channel=i%2==0?"CARD":"FASTER_PAYMENT";reference="TX"+a.substring(a.length()-4)+i;}}
@Entity @Table(name="cards") class CoreCard{@Id String id;String accountNumber;String customerId;String maskedNumber;String status;String blockReason;String replacementOf;protected CoreCard(){}CoreCard(String i,String a,String c,String n,String s){id=i;accountNumber=a;customerId=c;maskedNumber=n;status=s;}}
@Entity @Table(name="core_postings",uniqueConstraints=@UniqueConstraint(columnNames={"requestId","operation"})) class CorePosting{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;String requestId;String operation;String customerId;BigDecimal amount;String coreReference;Instant postedAt;protected CorePosting(){}CorePosting(String r,String o,String c,BigDecimal a){requestId=r;operation=o;customerId=c;amount=a;coreReference="CORE-"+r;postedAt=Instant.now();}}
